//! Test MCP tools with various output types (string, integer, object)
//!
//! MCP structured output requires JSON objects. This test verifies behavior
//! when tools return non-object types like bare strings or integers.

use sacp::mcp_server::McpServer;
use sacp::{Conductor, ConnectTo, DynConnectTo, Proxy, RunWithConnectionTo};
use sacp_conductor::{ConductorImpl, ProxiesAndAgent};
use sacp_test::testy::{Testy, TestyCommand};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

/// Empty input for test tools
#[derive(Debug, Serialize, Deserialize, JsonSchema)]
struct EmptyInput {}

/// Create a proxy with tools that return different types
fn create_test_proxy() -> Result<DynConnectTo<Conductor>, sacp::Error> {
    let mcp_server = McpServer::builder("test_server".to_string())
        .instructions("Test MCP server with various output types")
        .tool_fn_mut(
            "return_string",
            "Returns a bare string",
            async |_input: EmptyInput, _context| Ok("hello world".to_string()),
            sacp::tool_fn_mut!(),
        )
        .tool_fn_mut(
            "return_integer",
            "Returns a bare integer",
            async |_input: EmptyInput, _context| Ok(42i32),
            sacp::tool_fn_mut!(),
        )
        .build();

    Ok(DynConnectTo::new(ProxyWithTestServer { mcp_server }))
}

struct ProxyWithTestServer<R: RunWithConnectionTo<Conductor>> {
    mcp_server: McpServer<Conductor, R>,
}

impl<R: RunWithConnectionTo<Conductor> + 'static + Send> ConnectTo<Conductor>
    for ProxyWithTestServer<R>
{
    async fn connect_to(self, client: impl ConnectTo<Proxy>) -> Result<(), sacp::Error> {
        sacp::Proxy
            .builder()
            .name("test-proxy")
            .with_mcp_server(self.mcp_server)
            .connect_to(client)
            .await
    }
}

#[tokio::test]
async fn test_tool_returning_string() -> Result<(), sacp::Error> {
    let result = yopo::prompt(
        ConductorImpl::new_agent(
            "test-conductor".to_string(),
            ProxiesAndAgent::new(Testy::new()).proxy(create_test_proxy()?),
            Default::default(),
        ),
        TestyCommand::CallTool {
            server: "test_server".to_string(),
            tool: "return_string".to_string(),
            params: serde_json::json!({}),
        }
        .to_prompt(),
    )
    .await?;

    // The result should contain "hello world" somewhere
    assert!(
        result.contains("hello world"),
        "expected 'hello world' in result: {result}"
    );

    Ok(())
}

#[tokio::test]
async fn test_tool_returning_integer() -> Result<(), sacp::Error> {
    let result = yopo::prompt(
        ConductorImpl::new_agent(
            "test-conductor".to_string(),
            ProxiesAndAgent::new(Testy::new()).proxy(create_test_proxy()?),
            Default::default(),
        ),
        TestyCommand::CallTool {
            server: "test_server".to_string(),
            tool: "return_integer".to_string(),
            params: serde_json::json!({}),
        }
        .to_prompt(),
    )
    .await?;

    // The result should contain "42" somewhere
    assert!(result.contains("42"), "expected '42' in result: {result}");

    Ok(())
}

//! Tests for running McpServer as a standalone MCP server (not part of ACP).
//!
//! These tests verify that `McpServer` can be used directly with MCP clients
//! via the `Component<McpServerToClient>` implementation.

use rmcp::{ClientHandler, ServiceExt, model::ClientInfo};
use sacp::{
    ByteStreams, ConnectTo, RunWithConnectionTo, mcp_server::McpServer, role::mcp, util::run_until,
};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use tokio_util::compat::{TokioAsyncReadCompatExt, TokioAsyncWriteCompatExt};

/// Input for the echo tool
#[derive(Debug, Serialize, Deserialize, JsonSchema)]
struct EchoInput {
    message: String,
}

/// Input for the add tool
#[derive(Debug, Serialize, Deserialize, JsonSchema)]
struct AddInput {
    a: i32,
    b: i32,
}

/// Output for the add tool (structured output)
#[derive(Debug, Serialize, Deserialize, JsonSchema)]
struct AddOutput {
    result: i32,
}

/// Create a test MCP server with echo and add tools
fn create_test_server() -> McpServer<mcp::Client, impl RunWithConnectionTo<mcp::Client>> {
    McpServer::builder("test-server")
        .instructions("A test MCP server")
        .tool_fn(
            "echo",
            "Echo a message back",
            async |input: EchoInput, _cx| Ok(format!("Echo: {}", input.message)),
            sacp::tool_fn!(),
        )
        .tool_fn(
            "add",
            "Add two numbers",
            async |input: AddInput, _cx| {
                Ok(AddOutput {
                    result: input.a + input.b,
                })
            },
            sacp::tool_fn!(),
        )
        .build()
}

/// Minimal client handler for rmcp
#[derive(Debug, Clone, Default)]
struct MinimalClientHandler;

impl ClientHandler for MinimalClientHandler {
    fn get_info(&self) -> ClientInfo {
        ClientInfo::default()
    }
}

#[tokio::test]
async fn test_standalone_server_list_tools() -> Result<(), sacp::Error> {
    // Create duplex streams for communication
    let (server_stream, client_stream) = tokio::io::duplex(8192);
    let (server_read, server_write) = tokio::io::split(server_stream);
    let (client_read, client_write) = tokio::io::split(client_stream);

    // Create the MCP server
    let server = create_test_server();

    // Wrap client side as ByteStreams (this is what the MCP server will talk to)
    let client_as_component = ByteStreams::new(client_write.compat_write(), client_read.compat());

    run_until(
        ConnectTo::<mcp::Client>::connect_to(server, client_as_component),
        async move {
            // Create rmcp client on the server side of the duplex (the "other end")
            let client = MinimalClientHandler
                .serve((server_read, server_write))
                .await
                .map_err(sacp::util::internal_error)?;

            // List tools
            let tools_result = client
                .list_tools(None)
                .await
                .map_err(sacp::util::internal_error)?;

            // Verify we got both tools
            assert_eq!(tools_result.tools.len(), 2);

            let tool_names: Vec<&str> =
                tools_result.tools.iter().map(|t| t.name.as_ref()).collect();
            assert!(tool_names.contains(&"echo"));
            assert!(tool_names.contains(&"add"));

            // Clean up
            client.cancel().await.map_err(sacp::util::internal_error)?;
            Ok(())
        },
    )
    .await
}

#[tokio::test]
async fn test_standalone_server_call_echo_tool() -> Result<(), sacp::Error> {
    let (server_stream, client_stream) = tokio::io::duplex(8192);
    let (server_read, server_write) = tokio::io::split(server_stream);
    let (client_read, client_write) = tokio::io::split(client_stream);

    let server = create_test_server();
    let client_as_component = ByteStreams::new(client_write.compat_write(), client_read.compat());

    run_until(
        ConnectTo::<mcp::Client>::connect_to(server, client_as_component),
        async move {
            let client = MinimalClientHandler
                .serve((server_read, server_write))
                .await
                .map_err(sacp::util::internal_error)?;

            // Call the echo tool
            let result = client
                .call_tool(
                    rmcp::model::CallToolRequestParams::new("echo").with_arguments(
                        serde_json::json!({ "message": "hello world" })
                            .as_object()
                            .unwrap()
                            .clone(),
                    ),
                )
                .await
                .map_err(sacp::util::internal_error)?;

            // Verify the result
            let text = result
                .content
                .first()
                .and_then(|c| c.raw.as_text())
                .map(|t| t.text.as_str())
                .expect("Expected text content");

            assert_eq!(text, r#""Echo: hello world""#, "Unexpected echo response");

            client.cancel().await.map_err(sacp::util::internal_error)?;
            Ok(())
        },
    )
    .await
}

#[tokio::test]
async fn test_standalone_server_call_add_tool() -> Result<(), sacp::Error> {
    let (server_stream, client_stream) = tokio::io::duplex(8192);
    let (server_read, server_write) = tokio::io::split(server_stream);
    let (client_read, client_write) = tokio::io::split(client_stream);

    let server = create_test_server();
    let client_as_component = ByteStreams::new(client_write.compat_write(), client_read.compat());

    run_until(
        ConnectTo::<mcp::Client>::connect_to(server, client_as_component),
        async move {
            let client = MinimalClientHandler
                .serve((server_read, server_write))
                .await
                .map_err(sacp::util::internal_error)?;

            // Call the add tool
            let result = client
                .call_tool(
                    rmcp::model::CallToolRequestParams::new("add").with_arguments(
                        serde_json::json!({ "a": 5, "b": 3 })
                            .as_object()
                            .unwrap()
                            .clone(),
                    ),
                )
                .await
                .map_err(sacp::util::internal_error)?;

            // The add tool returns structured output (AddOutput)
            // Check that we get the expected result
            assert!(!result.is_error.unwrap_or(false));

            // Structured output should have the result
            let content = result.content.first().expect("Expected content");
            let text = content.raw.as_text().expect("Expected text content");
            assert!(
                text.text.contains("8") || text.text.contains("result"),
                "Expected result to contain 8, got: {}",
                text.text
            );

            client.cancel().await.map_err(sacp::util::internal_error)?;
            Ok(())
        },
    )
    .await
}

#[tokio::test]
async fn test_standalone_server_tool_not_found() -> Result<(), sacp::Error> {
    let (server_stream, client_stream) = tokio::io::duplex(8192);
    let (server_read, server_write) = tokio::io::split(server_stream);
    let (client_read, client_write) = tokio::io::split(client_stream);

    let server = create_test_server();
    let client_as_component = ByteStreams::new(client_write.compat_write(), client_read.compat());

    run_until(
        ConnectTo::<mcp::Client>::connect_to(server, client_as_component),
        async move {
            let client = MinimalClientHandler
                .serve((server_read, server_write))
                .await
                .map_err(sacp::util::internal_error)?;

            // Call a non-existent tool
            let result = client
                .call_tool(rmcp::model::CallToolRequestParams::new("nonexistent"))
                .await;

            // Should get an error
            assert!(result.is_err(), "Expected error for non-existent tool");

            client.cancel().await.map_err(sacp::util::internal_error)?;
            Ok(())
        },
    )
    .await
}

#[tokio::test]
async fn test_standalone_server_with_disabled_tools() -> Result<(), sacp::Error> {
    let (server_stream, client_stream) = tokio::io::duplex(8192);
    let (server_read, server_write) = tokio::io::split(server_stream);
    let (client_read, client_write) = tokio::io::split(client_stream);

    // Create server with echo tool disabled
    let server = McpServer::builder("test-server")
        .tool_fn(
            "echo",
            "Echo a message",
            async |input: EchoInput, _cx| Ok(format!("Echo: {}", input.message)),
            sacp::tool_fn!(),
        )
        .tool_fn(
            "add",
            "Add two numbers",
            async |input: AddInput, _cx| {
                Ok(AddOutput {
                    result: input.a + input.b,
                })
            },
            sacp::tool_fn!(),
        )
        .disable_tool("echo")?
        .build();

    let client_as_component = ByteStreams::new(client_write.compat_write(), client_read.compat());

    run_until(
        ConnectTo::<mcp::Client>::connect_to(server, client_as_component),
        async move {
            let client = MinimalClientHandler
                .serve((server_read, server_write))
                .await
                .map_err(sacp::util::internal_error)?;

            // List tools - should only show "add"
            let tools_result = client
                .list_tools(None)
                .await
                .map_err(sacp::util::internal_error)?;
            assert_eq!(tools_result.tools.len(), 1);
            assert_eq!(tools_result.tools[0].name.as_ref(), "add");

            // Calling disabled tool should fail
            let result = client
                .call_tool(
                    rmcp::model::CallToolRequestParams::new("echo").with_arguments(
                        serde_json::json!({ "message": "test" })
                            .as_object()
                            .unwrap()
                            .clone(),
                    ),
                )
                .await;

            assert!(result.is_err(), "Expected error for disabled tool");

            client.cancel().await.map_err(sacp::util::internal_error)?;
            Ok(())
        },
    )
    .await
}

//! Test that MCP server doesn't break the handler chain for NewSessionRequest.
//!
//! This is a regression test for a bug where `McpServer::handle_dispatch` would
//! forward `NewSessionRequest` directly to the agent instead of returning
//! `Handled::No`, which prevented downstream `.on_receive_request_from()` handlers
//! from being invoked.

use sacp::mcp_server::McpServer;
use sacp::schema::{
    AgentCapabilities, InitializeRequest, InitializeResponse, NewSessionRequest,
    NewSessionResponse, ProtocolVersion, SessionId,
};
use sacp::{Agent, Client, Conductor, ConnectTo, DynConnectTo, Proxy};
use sacp_conductor::{ConductorImpl, ProxiesAndAgent};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};

use tokio::io::duplex;
use tokio_util::compat::{TokioAsyncReadCompatExt, TokioAsyncWriteCompatExt};

/// Simple echo tool parameters
#[derive(Debug, Serialize, Deserialize, JsonSchema)]
struct EchoParams {
    message: String,
}

/// Simple echo tool output
#[derive(Debug, Serialize, Deserialize, JsonSchema)]
struct EchoOutput {
    result: String,
}

/// Test helper to receive a JSON-RPC response
async fn recv<T: sacp::JsonRpcResponse + Send>(
    response: sacp::SentRequest<T>,
) -> Result<T, sacp::Error> {
    let (tx, rx) = tokio::sync::oneshot::channel();
    response.on_receiving_result(async move |result| {
        tx.send(result).map_err(|_| sacp::Error::internal_error())
    })?;
    rx.await.map_err(|_| sacp::Error::internal_error())?
}

/// Tracks whether the NewSessionRequest handler was invoked
struct HandlerConfig {
    new_session_handler_called: AtomicBool,
}

impl HandlerConfig {
    fn new() -> Arc<Self> {
        Arc::new(Self {
            new_session_handler_called: AtomicBool::new(false),
        })
    }

    fn was_handler_called(&self) -> bool {
        self.new_session_handler_called.load(Ordering::SeqCst)
    }
}

/// A proxy component that has BOTH an MCP server AND a NewSessionRequest handler.
/// The bug was that when both were present, the NewSessionRequest handler was never called.
struct ProxyWithMcpAndHandler {
    config: Arc<HandlerConfig>,
}

impl ConnectTo<Conductor> for ProxyWithMcpAndHandler {
    async fn connect_to(self, client: impl ConnectTo<Proxy>) -> Result<(), sacp::Error> {
        let config = Arc::clone(&self.config);

        // Create an MCP server with a simple tool
        let mcp_server = McpServer::builder("test-server".to_string())
            .instructions("A test MCP server")
            .tool_fn_mut(
                "echo",
                "Echoes back the input",
                async |params: EchoParams, _cx| {
                    Ok(EchoOutput {
                        result: format!("Echo: {}", params.message),
                    })
                },
                sacp::tool_fn_mut!(),
            )
            .build();

        sacp::Proxy
            .builder()
            .name("proxy-with-mcp-and-handler")
            // Add the MCP server
            .with_mcp_server(mcp_server)
            // Add a NewSessionRequest handler - this should be invoked!
            .on_receive_request_from(
                Client,
                async move |request: NewSessionRequest, responder, cx| {
                    // Mark that we were called
                    config
                        .new_session_handler_called
                        .store(true, Ordering::SeqCst);

                    // Forward to agent and relay response
                    cx.send_request_to(Agent, request)
                        .on_receiving_result(async move |result| {
                            let response: NewSessionResponse = result?;
                            responder.respond(response)
                        })
                },
                sacp::on_receive_request!(),
            )
            .connect_to(client)
            .await
    }
}

/// A simple agent that responds to initialization and session requests
struct SimpleAgent;

impl ConnectTo<Client> for SimpleAgent {
    async fn connect_to(self, client: impl ConnectTo<Agent>) -> Result<(), sacp::Error> {
        Agent
            .builder()
            .name("simple-agent")
            .on_receive_request(
                async |request: InitializeRequest, responder, _cx| {
                    responder.respond(
                        InitializeResponse::new(request.protocol_version)
                            .agent_capabilities(AgentCapabilities::new()),
                    )
                },
                sacp::on_receive_request!(),
            )
            .on_receive_request(
                async |_request: NewSessionRequest, responder, _cx| {
                    responder.respond(NewSessionResponse::new(SessionId::new(
                        uuid::Uuid::new_v4().to_string(),
                    )))
                },
                sacp::on_receive_request!(),
            )
            .connect_to(client)
            .await
    }
}

async fn run_test(
    proxies: Vec<DynConnectTo<Conductor>>,
    agent: DynConnectTo<Client>,
    editor_task: impl AsyncFnOnce(sacp::ConnectionTo<Agent>) -> Result<(), sacp::Error>,
) -> Result<(), sacp::Error> {
    let (editor_out, conductor_in) = duplex(1024);
    let (conductor_out, editor_in) = duplex(1024);

    let transport = sacp::ByteStreams::new(editor_out.compat_write(), editor_in.compat());

    sacp::Client
        .builder()
        .name("editor-to-conductor")
        .with_spawned(|_cx| async move {
            ConductorImpl::new_agent(
                "conductor".to_string(),
                ProxiesAndAgent::new(agent).proxies(proxies),
                Default::default(),
            )
            .run(sacp::ByteStreams::new(
                conductor_out.compat_write(),
                conductor_in.compat(),
            ))
            .await
        })
        .connect_with(transport, editor_task)
        .await
}

/// Regression test: NewSessionRequest handler should be invoked even when MCP server is present
#[tokio::test]
async fn test_new_session_handler_invoked_with_mcp_server() -> Result<(), sacp::Error> {
    let handler_config = HandlerConfig::new();
    let handler_config_clone = Arc::clone(&handler_config);

    let proxy = DynConnectTo::<Conductor>::new(ProxyWithMcpAndHandler {
        config: handler_config,
    });
    let agent = DynConnectTo::<Client>::new(SimpleAgent);

    run_test(vec![proxy], agent, async |connection_to_editor| {
        // Initialize first
        let _init_response = recv(
            connection_to_editor.send_request(InitializeRequest::new(ProtocolVersion::LATEST)),
        )
        .await?;

        // Create a new session - this should trigger the handler in the proxy
        let session_response =
            recv(connection_to_editor.send_request(NewSessionRequest::new(PathBuf::from("/tmp"))))
                .await?;

        // Verify we got a valid session ID
        assert!(
            !session_response.session_id.0.is_empty(),
            "Should receive a valid session ID"
        );

        Ok::<(), sacp::Error>(())
    })
    .await?;

    // THE KEY ASSERTION: verify the handler was actually called
    assert!(
        handler_config_clone.was_handler_called(),
        "NewSessionRequest handler should be invoked even when MCP server is in the chain. \
         This is a regression - the MCP server was incorrectly forwarding the request directly \
         to the agent instead of letting it flow through the handler chain."
    );

    Ok(())
}

//! Integration test verifying that MCP tools receive the correct session_id
//!
//! This test verifies the complete flow:
//! 1. Editor creates a session and receives a session_id
//! 2. Proxy provides an MCP server with an echo tool
//! 3. Test agent invokes the tool
//! 4. The tool receives the correct session_id in its context
//! 5. The tool returns the session_id in its response
//! 6. We verify the session_ids match

use sacp::RunWithConnectionTo;
use sacp::mcp_server::McpServer;
use sacp::{Conductor, ConnectTo, DynConnectTo, Proxy};
use sacp_conductor::{ConductorImpl, ProxiesAndAgent};
use sacp_test::testy::{Testy, TestyCommand};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

/// Input for the echo tool (null/empty)
#[derive(Debug, Serialize, Deserialize, JsonSchema)]
struct EchoInput {}

/// Output from the echo tool containing the session_id
#[derive(Debug, Serialize, Deserialize, JsonSchema)]
struct EchoOutput {
    acp_url: String,
}

/// Create a proxy that provides an MCP server with a session_id echo tool
fn create_echo_proxy() -> Result<DynConnectTo<Conductor>, sacp::Error> {
    // Create MCP server with an echo tool that returns the session_id
    let mcp_server = McpServer::builder("echo_server".to_string())
        .instructions("Test MCP server with session_id echo tool")
        .tool_fn_mut(
            "echo",
            "Returns the current session_id",
            async |_input: EchoInput, context| {
                Ok(EchoOutput {
                    acp_url: context.acp_url(),
                })
            },
            sacp::tool_fn_mut!(),
        )
        .build();

    // Create proxy component
    Ok(DynConnectTo::new(ProxyWithEchoServer { mcp_server }))
}

struct ProxyWithEchoServer<R: RunWithConnectionTo<Conductor>> {
    mcp_server: McpServer<Conductor, R>,
}

impl<R: RunWithConnectionTo<Conductor> + 'static + Send> ConnectTo<Conductor>
    for ProxyWithEchoServer<R>
{
    async fn connect_to(self, client: impl ConnectTo<Proxy>) -> Result<(), sacp::Error> {
        sacp::Proxy
            .builder()
            .name("echo-proxy")
            .with_mcp_server(self.mcp_server)
            .connect_to(client)
            .await
    }
}

#[tokio::test]
async fn test_list_tools_from_mcp_server() -> Result<(), sacp::Error> {
    use expect_test::expect;

    let result = yopo::prompt(
        ConductorImpl::new_agent(
            "test-conductor".to_string(),
            ProxiesAndAgent::new(Testy::new()).proxy(create_echo_proxy()?),
            Default::default(),
        ),
        TestyCommand::ListTools {
            server: "echo_server".to_string(),
        }
        .to_prompt(),
    )
    .await?;

    // Check the response using expect_test
    expect![[r#"
        Available tools:
          - echo: Returns the current session_id"#]]
    .assert_eq(&result);

    Ok(())
}

#[tokio::test]
async fn test_session_id_delivered_to_mcp_tools() -> Result<(), sacp::Error> {
    let result = yopo::prompt(
        ConductorImpl::new_agent(
            "test-conductor".to_string(),
            ProxiesAndAgent::new(Testy::new()).proxy(create_echo_proxy()?),
            Default::default(),
        ),
        TestyCommand::CallTool {
            server: "echo_server".to_string(),
            tool: "echo".to_string(),
            params: serde_json::json!({}),
        }
        .to_prompt(),
    )
    .await?;

    let pattern = regex::Regex::new(r#""acp_url":\s*String\("acp:[0-9a-f-]+"\)"#).unwrap();
    assert!(pattern.is_match(&result), "unexpected result: {result}");

    Ok(())
}

//! Test that MCP servers can reference stack-local data.
//!
//! This test demonstrates the new scoped lifetime feature where an MCP tool
//! can capture references to stack-local data (like a Vec) and push to it
//! when the tool is invoked.

use sacp::mcp_server::McpServer;
use sacp::{Agent, Conductor, ConnectTo, Proxy, Role, RunWithConnectionTo};
use sacp_conductor::{ConductorImpl, McpBridgeMode, ProxiesAndAgent};
use sacp_test::testy::{Testy, TestyCommand};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use std::sync::Mutex;

/// Test that an MCP tool can push to a stack-local vector.
///
/// This validates the scoped lifetime feature - the tool closure captures
/// a reference to `collected_values` which lives on the stack.
#[tokio::test]
async fn test_scoped_mcp_server_through_proxy() -> Result<(), sacp::Error> {
    let conductor = ConductorImpl::new_agent(
        "conductor".to_string(),
        ProxiesAndAgent::new(Testy::new()).proxy(ScopedProxy),
        Default::default(),
    );

    let result = yopo::prompt(
        conductor,
        TestyCommand::CallTool {
            server: "test".to_string(),
            tool: "push".to_string(),
            params: serde_json::json!({"elements": ["Hello", "world"]}),
        }
        .to_prompt(),
    )
    .await?;

    expect_test::expect![[r#"
        "OK: CallToolResult { content: [Annotated { raw: Text(RawTextContent { text: \"2\", meta: None }), annotations: None }], structured_content: None, is_error: Some(false), meta: None }"
    "#]].assert_debug_eq(&result);

    Ok(())
}

/// Test that an MCP tool can push to a stack-local vector through a session.
///
/// This validates the scoped lifetime feature with session-scoped MCP servers.
/// The MCP server captures a reference to stack-local data that lives for
/// the duration of the session.
#[tokio::test]
async fn test_scoped_mcp_server_through_session() -> Result<(), sacp::Error> {
    // Run the client
    sacp::Client.builder()
        .connect_with(
